import{_ as a,a as t,c as n,ac as o}from"./chunks/framework.BSuaGltH.js";const g=JSON.parse('{"title":"第四册：流利英语 · 单元 4 语法总结","description":"L25–L32 规则、例句、易错点。","frontmatter":{"title":"第四册：流利英语 · 单元 4 语法总结","description":"L25–L32 规则、例句、易错点。","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"句法与表达查阅","scope":"general","audience":"general","group":"学习与记录","summary":"L25–L32 规则、例句、易错点。","status":"active","related":[{"title":"程序员英语 01：学习路线与能力自测","link":"/life/english/programmer/overview","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 02：技术词汇与句子骨架","link":"/life/english/programmer/vocabulary","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 03：读懂文档中的条件与约束","link":"/life/english/programmer/reading-docs","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 04：读报错、搜索与求助","link":"/life/english/programmer/errors-search","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 05：写 Issue、Commit 与 PR","link":"/life/english/programmer/issue-pr","kind":"路线与能力起点","scope":"general","audience":"general"}],"prev":{"text":"第四册：流利英语 · 单元 4：机制、反事实与专业沟通","link":"/life/english/new-concept/book-4/unit-04/overview"},"next":{"text":"第四册：流利英语 · 单元 4 单词与短语","link":"/life/english/new-concept/book-4/unit-04/vocabulary"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第四册：流利英语 · 单元 4：机制、反事实与专业沟通","link":"/life/english/new-concept/book-4/unit-04/overview"},"next":{"text":"第四册：流利英语 · 单元 4 单词与短语","link":"/life/english/new-concept/book-4/unit-04/vocabulary"}},"headers":[],"relativePath":"life/english/new-concept/book-4/unit-04/grammar.md","filePath":"life/english/new-concept/book-4/unit-04/grammar.md"}'),i={name:"life/english/new-concept/book-4/unit-04/grammar.md"};function r(s,e,l,h,p,c){return t(),n("div",null,[...e[0]||(e[0]=[o('<h1 id="第四册-流利英语-·-单元-4-语法总结" tabindex="-1">第四册：流利英语 · 单元 4 语法总结 <a class="header-anchor" href="#第四册-流利英语-·-单元-4-语法总结" aria-label="Permalink to &quot;第四册：流利英语 · 单元 4 语法总结&quot;">​</a></h1><p><a href="/life/english/new-concept/book-4/unit-04/overview">单元导读</a> · <a href="/life/english/new-concept/book-4/unit-04/grammar">单元语法总结</a> · <a href="/life/english/new-concept/book-4/unit-04/vocabulary">单元单词与短语</a> · <a href="/life/english/new-concept/book-4/unit-04/review">单元复习与自测</a></p><h2 id="名词化与施事信息" tabindex="-1">名词化与施事信息 <a class="header-anchor" href="#名词化与施事信息" aria-label="Permalink to &quot;名词化与施事信息&quot;">​</a></h2><p>名词化把动词或形容词转为名词表达，例如 people concentrate → concentration。它便于讨论抽象过程，但可能隐藏谁做了什么：a reduction in errors 没有说明谁减少了错误，也不说明原因。介词选择应随搭配，如 exposure to noise、an increase in interruptions。改写时保留时间、对象与证据强度，不能把 may affect 改成 the effect of 就暗中确认影响已存在。</p><p><strong>L25 原创例句：</strong> A reduction in background noise coincided with fewer interruptions during the task.</p><p>背景噪声的减少与任务过程中打断次数的下降同时出现。</p><p><strong>易错：</strong> exposure of noise 应改 exposure to noise；coincided with 也不能自动替换为 caused。</p><p><a href="/life/english/new-concept/book-4/unit-04/lesson-025">Lesson 25</a></p><h2 id="完成式分词状语" tabindex="-1">完成式分词状语 <a class="header-anchor" href="#完成式分词状语" aria-label="Permalink to &quot;完成式分词状语&quot;">​</a></h2><p>Having examined the layers, the team proposed a sequence. 中 having done 表示检查发生在提出之前，并与主句共享主语。若对象被检查，可用 having been examined，但要确保逻辑主语是被检查物。完成式分词突出先完成某事再做另一事，不必对所有有先后顺序的动作都使用。主语不一致时，用 after 引导完整从句更清楚，避免因压缩而造成悬垂修饰。</p><p><strong>L26 原创例句：</strong> Having compared the layers, the researchers proposed a tentative sequence of events.</p><p>比较地层之后，研究者提出了一个暂定的事件顺序。</p><p><strong>易错：</strong> Having compared the layers, a sequence was proposed 容易让 sequence 成为比较者；应明确主语 researchers。</p><p><a href="/life/english/new-concept/book-4/unit-04/lesson-026">Lesson 26</a></p><h2 id="第三条件句与过去反事实" tabindex="-1">第三条件句与过去反事实 <a class="header-anchor" href="#第三条件句与过去反事实" aria-label="Permalink to &quot;第三条件句与过去反事实&quot;">​</a></h2><p>If + had done，主句 would/could/might have done 用来设想已经过去的情形。If the team had checked the balance, they might have noticed the problem. 并不表示检查实际发生了。would have 通常把结果说得较确定，might have 更适合不确定的历史推测。不能把 if 从句写成 if would have checked。除非有明确时间转换，不要把过去条件与现在结果形式随意混用。</p><p><strong>L27 原创例句：</strong> If the model had been tested earlier, the designers might have noticed the imbalance.</p><p>如果模型更早接受了测试，设计者可能会注意到不平衡。</p><p><strong>易错：</strong> If the model would have been tested 错把结果形式放入条件；应写 had been tested。</p><p><a href="/life/english/new-concept/book-4/unit-04/lesson-027">Lesson 27</a></p><h2 id="间接问句与疑问语序" tabindex="-1">间接问句与疑问语序 <a class="header-anchor" href="#间接问句与疑问语序" aria-label="Permalink to &quot;间接问句与疑问语序&quot;">​</a></h2><p>Could you explain what the term means? 中 what 从句是 explain 的宾语，使用 the term means 的陈述语序，不保留直接问句 What does the term mean? 的 does。yes/no 问题可用 whether 或 if 引入。礼貌框架 Could you tell me 不会自动把从句变成过去时；从句时态应由所问内容决定。避免把礼貌间接问句写成多个问号或重复助动词。</p><p><strong>L28 原创例句：</strong> Could you explain what this term means in plain language?</p><p>您能用浅显的语言解释这个术语的含义吗？</p><p><strong>易错：</strong> Could you explain what does this term mean? 错用直接问句语序；应去 does 并用 means。</p><p><a href="/life/english/new-concept/book-4/unit-04/lesson-028">Lesson 28</a></p><h2 id="使役与许可结构" tabindex="-1">使役与许可结构 <a class="header-anchor" href="#使役与许可结构" aria-label="Permalink to &quot;使役与许可结构&quot;">​</a></h2><p>enable/allow + 宾语 + to do 表示使某人能够或允许某人做事；make + 宾语 + 动词原形表示使某人做事，主动结构不带 to。被动 be made to do 则恢复 to。The cushion allows the craft to move… 描述功能，不能写 allows the craft move。enable 强调能力或条件，allow 可表许可也可表条件允许；实际语义要结合装置或人的语境判断。</p><p><strong>L29 原创例句：</strong> The air cushion allows the model to move across the smooth floor.</p><p>气垫使这个模型能够在光滑地板上移动。</p><p><strong>易错：</strong> allows the model move 缺少 to；不要把 allow 的结构误套成 make 的结构。</p><p><a href="/life/english/new-concept/book-4/unit-04/lesson-029">Lesson 29</a></p><h2 id="介词-which-的关系从句" tabindex="-1">介词 + which 的关系从句 <a class="header-anchor" href="#介词-which-的关系从句" aria-label="Permalink to &quot;介词 + which 的关系从句&quot;">​</a></h2><p>the depth at which the instrument operates 中 which 指 depth，at 来自 operate at a depth。正式表达可把介词放在关系代词前；较口语的限制性从句可把介词放句尾，如 the depth which it operates at。介词后的关系代词不能用 that，也不能省略。选择介词应看动词或名词搭配，不能见到地点就一律用 in；pressure 常搭配 under。</p><p><strong>L30 原创例句：</strong> The pressure under which the sensor operates must be recorded.</p><p>必须记录传感器工作时所处的压力。</p><p><strong>易错：</strong> under that the sensor operates 不成立；介词前置的关系结构用 which。</p><p><a href="/life/english/new-concept/book-4/unit-04/lesson-030">Lesson 30</a></p><h2 id="独立主格的主语与分词" tabindex="-1">独立主格的主语与分词 <a class="header-anchor" href="#独立主格的主语与分词" aria-label="Permalink to &quot;独立主格的主语与分词&quot;">​</a></h2><p>独立主格结构有自己的名词或代词逻辑主语，如 The clay still wet, the artist covered the model。它可补充时间、原因或伴随背景，不必与主句主语一致。名词后可接分词、形容词或介词短语。与普通分词状语不同，Materials prepared, we began 中 prepared 的承受者是 materials。正式写作中应避免连续堆叠；背景关系可能含糊时，用 because 或 after 完整从句更清楚。</p><p><strong>L31 原创例句：</strong> The clay still damp, the sculptor covered the model before leaving.</p><p>黏土还湿着，雕塑家离开前盖住了模型。</p><p><strong>易错：</strong> 不要把独立主格误写成 The clay was still damp, the sculptor covered…；两个完整句不能仅用逗号连接。</p><p><a href="/life/english/new-concept/book-4/unit-04/lesson-031">Lesson 31</a></p><h2 id="形容词前置的-as-让步结构" tabindex="-1">形容词前置的 as 让步结构 <a class="header-anchor" href="#形容词前置的-as-让步结构" aria-label="Permalink to &quot;形容词前置的 as 让步结构&quot;">​</a></h2><p>形容词 + as + 主语 + be 可表示“尽管”，如 Limited as the evidence is, it deserves attention。它不同于表示原因的 As the evidence is limited…，语序和逻辑都不同。名词前置也可表让步，单数名词常不带冠词，如 Child as he was…；这种结构较正式。让步只承认前项，不取消后面的主句，但主句仍需独立理由支持，不能借修辞替代证据。</p><p><strong>L32 原创例句：</strong> Limited as the evidence is, it gives us a reason to repeat the experiment.</p><p>尽管证据有限，它仍给了我们重复实验的理由。</p><p><strong>易错：</strong> As the evidence is limited 通常更容易读成“因为证据有限”；要保留让步意思可用 Although 或前置 Limited as。</p><p><a href="/life/english/new-concept/book-4/unit-04/lesson-032">Lesson 32</a></p>',50)])])}const u=a(i,[["render",r]]);export{g as __pageData,u as default};
